Here's how to implement a basic routing system in React using React Router:

```jsx
import React from 'react';
import { BrowserRouter, Routes, Route, Link, useNavigate } from 'react-router-dom';

// Pages
function Home() {
    return (
        <div>
            <h1>Home Page</h1>
            <nav>
                <Link to="/about">About</Link>
                <Link to="/contact">Contact</Link>
                <Link to="/users">Users</Link>
            </nav>
        </div>
    );
}

function About() { return <h1>About Us</h1>; }
function Contact() { return <h1>Contact Us</h1>; }

function Users() {
    const navigate = useNavigate();
    const users = ['Alice', 'Bob', 'Charlie'];

    return (
        <div>
            <h1>Users</h1>
            <ul>
                {users.map((user, index) => (
                    <li key={index}>
                        <Link to={`/users/${user.toLowerCase()}`}>{user}</Link>
                    </li>
                ))}
            </ul>
            <button onClick={() => navigate('/')}>Back to Home</button>
        </div>
    );
}

function UserProfile() {
    const { userId } = useParams();
    return <h1>User Profile: {userId}</h1>;
}

// Main App with routing
function App() {
    return (
        <BrowserRouter>
            <Routes>
                <Route path="/" element={<Home />} />
                <Route path="/about" element={<About />} />
                <Route path="/contact" element={<Contact />} />
                <Route path="/users" element={<Users />} />
                <Route path="/users/:userId" element={<UserProfile />} />
                <Route path="*" element={<h1>404: Page Not Found</h1>} />
            </Routes>
        </BrowserRouter>
    );
}

export default App;
```

For a map with markers and routing, combine React Router with a map library like `react-leaflet` or `@react-google-maps/api`. The `<Routes>` component matches URL patterns to components, `<Link>` creates navigation links, and `useNavigate()` provides programmatic navigation.
